SELECT r.id, r.gateway_request_id, r.integration_id, r.conversation_binding_id, r.slack_event_id, r.slack_channel_id, r.slack_conversation_type, r.slack_thread_root_message_id, r.slack_prompt_message_id, r.slack_prompt_author_id, r.prompt_text, r.prompt_has_attachments, r.gateway_execution_state, r.gateway_execution_reason, r.gateway_execution_outcome, r.gateway_execution_result_text, r.gateway_execution_claim_count, r.backend_submission_started_at, r.backend_next_poll_at, r.backend_poll_attempts, r.backend_poll_ready, r.backend_observed_state, r.backend_observed_at, r.backend_observation_uncertain, r.slack_progress_mode, r.slack_progress_message_id, r.slack_progress_state, r.slack_progress_phase, r.slack_progress_reason, r.slack_progress_revision, r.slack_progress_sent_revision, r.slack_progress_attempts, r.slack_progress_next_attempt_at, r.slack_progress_refresh_at, r.slack_progress_rate_limited_until, r.slack_progress_first_sent_at, r.slack_progress_last_sent_at, r.created_at, r.gateway_execution_updated_at, r.gateway_status_updated_at, r.gateway_execution_finished_at, r.content_purged_at FROM (SELECT * FROM  (SELECT * FROM gateway_job j)  gateway_jobs) r WHERE $criteria.CompositeIn("r", $WriterKeys)